"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { FileText, Loader2, Calendar } from "lucide-react"
import { fetchGlobalBalanceSheet, type GlobalBalanceSheetResponse } from "@/lib/api"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Calendar as CalendarComponent } from "@/components/ui/calendar"
import { format } from "date-fns"

function StatementRow({
  label,
  amount,
  variant = "normal",
  transactionCount,
}: {
  label: string
  amount?: string | number
  variant?: "normal" | "indent" | "subtitle" | "total" | "grand-total"
  transactionCount?: number
}) {
  const baseStyles = "flex justify-between py-3 px-4 border-b border-border"
  const variantStyles = {
    normal: "",
    indent: "pl-10 text-muted-foreground",
    subtitle: "font-semibold text-primary bg-secondary mt-2",
    total: "font-semibold bg-secondary border-t-2 border-b-2 border-border mt-2",
    "grand-total": "bg-primary text-primary-foreground font-semibold text-lg mt-4",
  }

  const formatAmount = (amt: string | number | undefined) => {
    if (amt === undefined || amt === null) return ""
    const numAmount = typeof amt === "string" ? parseFloat(amt) : amt
    return `RWF ${numAmount.toLocaleString()}`
  }

  return (
    <div className={`${baseStyles} ${variantStyles[variant]}`}>
      <div className="flex items-center gap-2">
        <span>{label}</span>
        {transactionCount !== undefined && variant === "indent" && (
          <span className="text-xs text-muted-foreground">
            ({transactionCount} {transactionCount === 1 ? "transaction" : "transactions"})
          </span>
        )}
      </div>
      {amount !== undefined && (
        <span className="font-serif font-semibold tabular-nums">{formatAmount(amount)}</span>
      )}
    </div>
  )
}

export function ConsolidatedBalance() {
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [data, setData] = useState<GlobalBalanceSheetResponse | null>(null)
  const [selectedDate, setSelectedDate] = useState<Date>(new Date())
  const [isCalendarOpen, setIsCalendarOpen] = useState(false)

  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true)
        setError(null)
        const dateString = format(selectedDate, "yyyy-MM-dd")
        const response = await fetchGlobalBalanceSheet(dateString)
        console.log("Global Balance Sheet:", response)
        setData(response)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load balance sheet")
      } finally {
        setLoading(false)
      }
    }
    loadData()
  }, [selectedDate])

  const handleExportPDF = () => {
    // TODO: Implement PDF export
    console.log("Export PDF clicked")
  }

  if (loading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    )
  }

  if (error) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <p className="text-sm text-destructive">{error}</p>
            <p className="text-xs text-muted-foreground mt-2">
              Please try again or contact support
            </p>
          </div>
        </CardContent>
      </Card>
    )
  }

  if (!data || !data.summary) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <p className="text-sm text-muted-foreground">No balance sheet data available</p>
          </div>
        </CardContent>
      </Card>
    )
  }

  const { summary, companies } = data

  // Check if we have detailed company data
  const hasDetailedData = companies && companies.length > 0
  
  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between">
        <div>
          <CardTitle className="font-serif">Consolidated Balance Sheet</CardTitle>
          <p className="text-sm text-muted-foreground mt-1 italic">
            As at {format(selectedDate, "dd MMMM yyyy")}
          </p>
          <p className="text-xs text-muted-foreground mt-1">
            {summary.totalCompanies} {summary.totalCompanies === 1 ? "Company" : "Companies"}
          </p>
        </div>
        <div className="flex gap-2">
          <Popover open={isCalendarOpen} onOpenChange={setIsCalendarOpen}>
            <PopoverTrigger asChild>
              <Button variant="outline">
                <Calendar className="h-4 w-4 mr-2" />
                Change Date
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-auto p-0" align="end">
              <CalendarComponent
                mode="single"
                selected={selectedDate}
                onSelect={(date) => {
                  if (date) {
                    setSelectedDate(date)
                    setIsCalendarOpen(false)
                  }
                }}
                disabled={(date) => date > new Date()}
                initialFocus
              />
            </PopoverContent>
          </Popover>
          <Button
            onClick={handleExportPDF}
            className="bg-accent text-accent-foreground hover:bg-accent/90"
          >
            <FileText className="h-4 w-4 mr-2" />
            Export PDF
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-6">
          {/* Summary Statistics */}
          <div className="grid grid-cols-3 gap-4 p-4 bg-muted/50 rounded-lg">
            <div className="text-center">
              <p className="text-xs text-muted-foreground mb-1">Total Assets</p>
              <p className="text-lg font-bold font-mono tabular-nums">
                RWF {summary.totalAssets.toLocaleString()}
              </p>
            </div>
            <div className="text-center">
              <p className="text-xs text-muted-foreground mb-1">Total Liabilities</p>
              <p className="text-lg font-bold font-mono tabular-nums">
                RWF {summary.totalLiabilities.toLocaleString()}
              </p>
            </div>
            <div className="text-center">
              <p className="text-xs text-muted-foreground mb-1">Total Equity</p>
              <p className="text-lg font-bold font-mono tabular-nums">
                RWF {summary.totalEquity.toLocaleString()}
              </p>
            </div>
          </div>

          {/* Assets Section */}
          <div>
            <h3 className="text-lg font-serif font-semibold text-green-700 dark:text-green-400 border-b-2 border-green-700 dark:border-green-400 pb-2 mb-4">
              Assets
            </h3>
            
            {hasDetailedData ? (
              <>
                {companies.map((company, idx) => (
                  <StatementRow
                    key={`asset-${idx}`}
                    label={company.companyName}
                    amount={company.totalAssets}
                    variant="indent"
                  />
                ))}
              </>
            ) : (
              <div className="px-4 py-2 text-sm text-muted-foreground italic">
                No detailed breakdown available
              </div>
            )}
            
            <StatementRow
              label="Total Assets"
              amount={summary.totalAssets}
              variant="total"
            />
          </div>

          {/* Liabilities Section */}
          <div>
            <h3 className="text-lg font-serif font-semibold text-red-700 dark:text-red-400 border-b-2 border-red-700 dark:border-red-400 pb-2 mb-4">
              Liabilities
            </h3>
            
            {hasDetailedData ? (
              <>
                {companies.map((company, idx) => (
                  <StatementRow
                    key={`liab-${idx}`}
                    label={company.companyName}
                    amount={company.totalLiabilities}
                    variant="indent"
                  />
                ))}
              </>
            ) : (
              <div className="px-4 py-2 text-sm text-muted-foreground italic">
                No detailed breakdown available
              </div>
            )}
            
            <StatementRow
              label="Total Liabilities"
              amount={summary.totalLiabilities}
              variant="total"
            />
          </div>

          {/* Equity Section */}
          <div>
            <h3 className="text-lg font-serif font-semibold text-blue-700 dark:text-blue-400 border-b-2 border-blue-700 dark:border-blue-400 pb-2 mb-4">
              Equity
            </h3>
            
            {hasDetailedData ? (
              <>
                {companies.map((company, idx) => (
                  <div key={`equity-${idx}`}>
                    <StatementRow
                      label={company.companyName}
                      amount={company.totalEquity}
                      variant="indent"
                    />
                    {company.retainedEarnings !== undefined && company.retainedEarnings !== 0 && (
                      <div className="pl-16 py-1 text-sm text-muted-foreground flex justify-between px-4">
                        <span className="italic">└─ Retained Earnings</span>
                        <span className="font-mono tabular-nums">
                          RWF {company.retainedEarnings.toLocaleString()}
                        </span>
                      </div>
                    )}
                  </div>
                ))}
              </>
            ) : (
              <div className="px-4 py-2 text-sm text-muted-foreground italic">
                No detailed breakdown available
              </div>
            )}
            
            <StatementRow
              label="Total Equity"
              amount={summary.totalEquity}
              variant="total"
            />
          </div>

          {/* Grand Total */}
          <div className="mt-6">
            <StatementRow
              label="Total Liabilities & Equity"
              amount={summary.totalLiabilities + summary.totalEquity}
              variant="grand-total"
            />
          </div>

          {/* Balance Check */}
          <div className="mt-4 p-4 rounded-lg border-2 ${
            summary.balanceCheck === 'BALANCED' 
              ? 'bg-green-50 dark:bg-green-950/20 border-green-300 dark:border-green-800' 
              : 'bg-red-50 dark:bg-red-950/20 border-red-300 dark:border-red-800'
          }">
            <div className="flex justify-between items-center mb-2">
              <span className="font-semibold text-lg">Balance Check:</span>
              <span
                className={`font-bold text-xl ${
                  summary.balanceCheck === "BALANCED"
                    ? "text-green-700 dark:text-green-400"
                    : "text-red-700 dark:text-red-400"
                }`}
              >
                {summary.balanceCheck}
              </span>
            </div>
            <p className="text-xs text-muted-foreground text-center">
              Assets (RWF {summary.totalAssets.toLocaleString()}) ={" "}
              Liabilities (RWF {summary.totalLiabilities.toLocaleString()}) +{" "}
              Equity (RWF {summary.totalEquity.toLocaleString()})
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}