"use client"

import { useState, useMemo } from "react"
import { cn } from "@/lib/utils"
import { DashboardSidebar } from "./sidebar"
import { TopBar } from "./top-bar"

// Tab components
import { DashboardOverview } from "./tabs/dashboard-overview"
// import { CompaniesOverview } from "./tabs/companies-overview"
import { CompanyDetail } from "./tabs/company-detail"
import { ConsolidatedIncome } from "./tabs/consolidated-income"
import { ConsolidatedBalance } from "./tabs/consolidated-balance"
import { CashFlowAnalysis } from "./tabs/cashflow-analysis"
import { UserManagement } from "./tabs/user-management"
import { CategoryManagement } from "./tabs/category-management"
import { TransactionManagement } from "./tabs/record-transaction"
import CompaniesPage from "./tabs/companies-overview"

const pageTitles: Record<string, { title: string; breadcrumb: string }> = {
  dashboard: { title: "Group Financial Summary", breadcrumb: "IREBE Group / Dashboard" },
  companies: { title: "All Companies", breadcrumb: "IREBE Group / Companies" },
  construction: { title: "IREBE Construction Ltd", breadcrumb: "IREBE Group / Companies / Construction" },
  trading: { title: "IREBE Trading Ltd", breadcrumb: "IREBE Group / Companies / Trading" },
  logistics: { title: "IREBE Logistics Ltd", breadcrumb: "IREBE Group / Companies / Logistics" },
  tech: { title: "IREBE Tech Solutions Ltd", breadcrumb: "IREBE Group / Companies / Tech" },
  "consolidated-income": { title: "Consolidated Income Statement", breadcrumb: "IREBE Group / Reports / Income" },
  "consolidated-balance": { title: "Consolidated Balance Sheet", breadcrumb: "IREBE Group / Reports / Balance" },
  cashflow: { title: "Cash Flow Analysis", breadcrumb: "IREBE Group / Reports / Cash Flow" },
  record: { title: "Record Transaction", breadcrumb: "IREBE Group / Data Entry" },
  categories: { title: "Category Management", breadcrumb: "IREBE Group / Admin / Categories" },
  users: { title: "User Management", breadcrumb: "IREBE Group / Admin / Users" },
}

export function DashboardLayout() {
  const [activeTab, setActiveTab] = useState("dashboard")
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)

  const currentPage = pageTitles[activeTab] || pageTitles.dashboard

  const tabContent = useMemo(() => {
    switch (activeTab) {
      case "dashboard":
        return <DashboardOverview onNavigate={setActiveTab} />
      case "companies":
        // onNavigate={setActiveTab} 
        return <CompaniesPage />
      case "construction":
        return <CompanyDetail company="construction" />
      case "trading":
        return <CompanyDetail company="trading" />
      case "logistics":
        return <CompanyDetail company="logistics" />
      case "tech":
        return <CompanyDetail company="tech" />
      case "consolidated-income":
        return <ConsolidatedIncome />
      case "consolidated-balance":
        return <ConsolidatedBalance />
      case "cashflow":
        return <CashFlowAnalysis />
      case "record":
        return <TransactionManagement />
      case "categories":
        return <CategoryManagement />
      case "users":
        return <UserManagement />
      default:
        return <DashboardOverview onNavigate={setActiveTab} />
    }
  }, [activeTab])

  return (
    <div className="min-h-screen bg-background">
      <DashboardSidebar
        activeTab={activeTab}
        onTabChange={setActiveTab}
        collapsed={sidebarCollapsed}
        onToggleCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
      />
      <main
        className={cn(
          "transition-all duration-300",
          sidebarCollapsed ? "ml-16" : "ml-64"
        )}
      >
        <TopBar title={currentPage.title} breadcrumb={currentPage.breadcrumb} />
        <div className="p-6">{tabContent}</div>
      </main>
    </div>
  )
}
